CREATE TABLE IF NOT EXISTS admin_users (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, created_at TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE NOT NULL, base_path TEXT NOT NULL, created_at TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS sites (id INTEGER PRIMARY KEY AUTOINCREMENT, server_user_id INTEGER, name TEXT NOT NULL, path TEXT NOT NULL, type TEXT NOT NULL DEFAULT 'unknown', cms_type TEXT NULL, cms_version TEXT NULL, cms_detected_at DATETIME NULL, cms_confidence INTEGER NULL, cms_admin_path TEXT NULL, cms_notes TEXT NULL, is_active INTEGER NOT NULL DEFAULT 1, last_scan_at TEXT NULL, created_at TEXT, updated_at TEXT, FOREIGN KEY(server_user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS scan_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, started_at TEXT NOT NULL, finished_at TEXT NULL, status TEXT NOT NULL DEFAULT 'running', scope_type TEXT NOT NULL DEFAULT 'full', scope_value TEXT NULL, profile TEXT NOT NULL DEFAULT 'fast', files_scanned INTEGER NOT NULL DEFAULT 0, skipped_media INTEGER NOT NULL DEFAULT 0, skipped_directories INTEGER NOT NULL DEFAULT 0, findings_count INTEGER NOT NULL DEFAULT 0, findings_new INTEGER NOT NULL DEFAULT 0, pid INTEGER NULL, current_site TEXT NULL, current_path TEXT NULL, total_files_estimated INTEGER NULL, last_heartbeat_at TEXT NULL, progress_message TEXT NULL, error_text TEXT NULL, scan_mode TEXT NOT NULL DEFAULT 'differential', previous_scan_id INTEGER NULL, files_seen_total INTEGER NOT NULL DEFAULT 0, files_new INTEGER NOT NULL DEFAULT 0, files_modified INTEGER NOT NULL DEFAULT 0, files_deleted INTEGER NOT NULL DEFAULT 0, files_changed_total INTEGER NOT NULL DEFAULT 0, files_analyzed INTEGER NOT NULL DEFAULT 0, files_skipped_unchanged INTEGER NOT NULL DEFAULT 0, diff_summary TEXT NULL, site_manifest_hash TEXT NULL, file_list_hash TEXT NULL, directory_list_hash TEXT NULL, metadata_hash TEXT NULL, created_at TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS file_snapshots (id INTEGER PRIMARY KEY AUTOINCREMENT, site_id INTEGER NULL, path TEXT NOT NULL, path_hash TEXT NOT NULL, relative_path TEXT NULL, owner TEXT NULL, "group" TEXT NULL, permissions TEXT NULL, size INTEGER NOT NULL DEFAULT 0, mtime TEXT NULL, ctime TEXT NULL, inode TEXT NULL, mode TEXT NULL, uid TEXT NULL, gid TEXT NULL, extension TEXT NULL, file_category TEXT NULL, content_hash TEXT NULL, first_seen_scan_id INTEGER NULL, last_seen_scan_id INTEGER NULL, last_changed_scan_id INTEGER NULL, baseline_status TEXT NULL, trusted_baseline_at TEXT NULL, sha256 TEXT NULL, first_seen_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, last_changed_at TEXT NULL, is_missing INTEGER NOT NULL DEFAULT 0, created_at TEXT, updated_at TEXT, FOREIGN KEY(site_id) REFERENCES sites(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS findings (id INTEGER PRIMARY KEY AUTOINCREMENT, scan_run_id INTEGER NULL, site_id INTEGER NULL, path TEXT NOT NULL, path_hash TEXT NOT NULL, finding_hash TEXT NOT NULL, risk TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', type TEXT NOT NULL DEFAULT 'unknown', rule_key TEXT NULL, fingerprint TEXT NULL, title TEXT NOT NULL, description TEXT NULL, matched_rules TEXT NULL, related_log_event_ids TEXT NULL, sha256 TEXT NULL, size INTEGER NULL, mtime TEXT NULL, owner TEXT NULL, permissions TEXT NULL, first_seen_at TEXT NULL, last_seen_at TEXT NULL, first_seen_scan_id INTEGER NULL, last_seen_scan_id INTEGER NULL, last_matched_signature_id INTEGER NULL, matched_signature_name TEXT NULL, matched_signature_source TEXT NULL, signature_match_details TEXT NULL, created_at TEXT, updated_at TEXT, FOREIGN KEY(scan_run_id) REFERENCES scan_runs(id) ON DELETE SET NULL, FOREIGN KEY(site_id) REFERENCES sites(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS scan_run_findings (scan_run_id INTEGER NOT NULL, finding_id INTEGER NOT NULL, observed_at TEXT NULL, PRIMARY KEY (scan_run_id,finding_id), FOREIGN KEY(scan_run_id) REFERENCES scan_runs(id) ON DELETE CASCADE, FOREIGN KEY(finding_id) REFERENCES findings(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS log_events (id INTEGER PRIMARY KEY AUTOINCREMENT, site_id INTEGER NULL, log_path TEXT NOT NULL, line_number INTEGER NULL, ip TEXT NULL, method TEXT NULL, uri TEXT NULL, uri_hash TEXT NULL, status_code INTEGER NULL, user_agent TEXT NULL, referer TEXT NULL, event_type TEXT NOT NULL, risk TEXT NOT NULL, raw_line TEXT NOT NULL, created_at TEXT, updated_at TEXT, FOREIGN KEY(site_id) REFERENCES sites(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS quarantine_items (id INTEGER PRIMARY KEY AUTOINCREMENT, finding_id INTEGER NULL, original_path TEXT NOT NULL, original_path_hash TEXT NULL, quarantine_path TEXT NOT NULL, sha256 TEXT NULL, owner TEXT NULL, "group" TEXT NULL, permissions TEXT NULL, mtime TEXT NULL, reason TEXT NULL, status TEXT NOT NULL DEFAULT 'quarantined', created_at TEXT, updated_at TEXT, FOREIGN KEY(finding_id) REFERENCES findings(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS rules (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT NULL, risk TEXT NOT NULL, type TEXT NOT NULL, pattern TEXT NOT NULL, pattern_type TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS allowlist_rules (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, path_pattern TEXT NULL, sha256 TEXT NULL, reason TEXT NULL, enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY AUTOINCREMENT, key TEXT UNIQUE NOT NULL, value TEXT NULL, created_at TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS restore_actions (id INTEGER PRIMARY KEY AUTOINCREMENT, admin_user_id INTEGER NULL, original_path TEXT NOT NULL, backup_provider TEXT NOT NULL, backup_user TEXT NULL, backup_date TEXT NULL, backup_source_archive TEXT NULL, previous_sha256 TEXT NULL, restored_sha256 TEXT NULL, previous_size INTEGER NULL, restored_size INTEGER NULL, quarantine_path TEXT NULL, created_at TEXT, status TEXT NOT NULL DEFAULT 'pending', error_message TEXT NULL);
CREATE TABLE IF NOT EXISTS ai_analyses (id INTEGER PRIMARY KEY AUTOINCREMENT, finding_id INTEGER NOT NULL, provider TEXT NULL, model TEXT NULL, risk TEXT NULL, confidence REAL NULL, summary TEXT NULL, raw_response TEXT NULL, created_at TEXT, updated_at TEXT, FOREIGN KEY(finding_id) REFERENCES findings(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS sites_path_prefix_idx ON sites(substr(path,1,191));
CREATE UNIQUE INDEX IF NOT EXISTS uniq_file_snapshots_path_hash ON file_snapshots(path_hash);
CREATE INDEX IF NOT EXISTS idx_file_snapshots_path_prefix ON file_snapshots(substr(path,1,191));
CREATE INDEX IF NOT EXISTS file_snapshots_site_id_idx ON file_snapshots(site_id);
CREATE INDEX IF NOT EXISTS file_snapshots_sha256_idx ON file_snapshots(sha256);
CREATE INDEX IF NOT EXISTS idx_findings_path_hash ON findings(path_hash);
CREATE INDEX IF NOT EXISTS idx_findings_path_prefix ON findings(substr(path,1,191));
CREATE INDEX IF NOT EXISTS findings_status_idx ON findings(status);
CREATE INDEX IF NOT EXISTS findings_risk_idx ON findings(risk);
CREATE INDEX IF NOT EXISTS findings_site_id_idx ON findings(site_id);
CREATE INDEX IF NOT EXISTS findings_finding_hash_idx ON findings(finding_hash,status);
CREATE INDEX IF NOT EXISTS scan_run_findings_finding_idx ON scan_run_findings(finding_id);
CREATE INDEX IF NOT EXISTS scan_runs_status_idx ON scan_runs(status);
CREATE INDEX IF NOT EXISTS log_events_site_id_idx ON log_events(site_id);
CREATE INDEX IF NOT EXISTS log_events_uri_hash_idx ON log_events(uri_hash);
CREATE INDEX IF NOT EXISTS log_events_uri_prefix_idx ON log_events(substr(uri,1,191));
CREATE INDEX IF NOT EXISTS log_events_ip_idx ON log_events(ip);
CREATE INDEX IF NOT EXISTS idx_quarantine_original_path_hash ON quarantine_items(original_path_hash);
CREATE INDEX IF NOT EXISTS quarantine_items_original_path_prefix_idx ON quarantine_items(substr(original_path,1,191));

CREATE TABLE IF NOT EXISTS malware_signatures (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT NULL, risk TEXT NOT NULL, type TEXT NOT NULL, pattern_type TEXT NOT NULL, pattern_json TEXT NOT NULL, target_extensions TEXT NULL, target_paths TEXT NULL, exclude_paths TEXT NULL, required_hits INTEGER NULL, enabled INTEGER NOT NULL DEFAULT 1, source TEXT NOT NULL DEFAULT 'manual', source_finding_id INTEGER NULL, source_file_sha256 TEXT NULL, confidence REAL NULL, false_positive_notes TEXT NULL, created_at TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS signature_suggestions (id INTEGER PRIMARY KEY AUTOINCREMENT, finding_id INTEGER NULL, source_file_path TEXT NULL, source_file_sha256 TEXT NULL, ai_provider TEXT NULL, model TEXT NULL, status TEXT NOT NULL DEFAULT 'draft', suggested_name TEXT NULL, suggested_risk TEXT NULL, suggested_type TEXT NULL, suggested_pattern_type TEXT NULL, suggested_pattern_json TEXT NULL, explanation TEXT NULL, test_result_json TEXT NULL, created_at TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS site_path_whitelist (id INTEGER PRIMARY KEY AUTOINCREMENT, site_id INTEGER NULL, path TEXT NOT NULL, path_type TEXT NOT NULL DEFAULT 'file', reason TEXT NULL, approved_by INTEGER NULL, approved_at TEXT NULL, expires_at TEXT NULL, created_at TEXT, updated_at TEXT);

CREATE INDEX IF NOT EXISTS file_snapshots_site_path_hash_idx ON file_snapshots(site_id, path_hash);
CREATE INDEX IF NOT EXISTS file_snapshots_site_last_seen_idx ON file_snapshots(site_id, last_seen_scan_id);
CREATE INDEX IF NOT EXISTS scan_runs_site_status_finished_idx ON scan_runs(scope_type, status, finished_at);
